mod emit;
mod fields;

use crate::DynError;
use proc_macro2::TokenStream;
use std::{
    fs, io,
    path::Path,
    process::{Command, Stdio},
};
use syn::Item;

const GENERATED_HEADER: &str =
    "// @generated by `cargo run -p hubuum_reconcile -- update`; do not edit by hand.";

pub(crate) fn generate_file(path: &Path) -> Result<String, DynError> {
    let source = fs::read_to_string(path)?;
    let file = syn::parse_file(&source)?;
    let mut generated = TokenStream::new();
    for item in file.items {
        generated.extend(expand_item(item)?);
    }
    format_generated(generated)
}

fn format_generated(tokens: TokenStream) -> Result<String, DynError> {
    let input = format!("{GENERATED_HEADER}\n{tokens}\n");
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--emit", "stdout"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| io::Error::new(error.kind(), format!("failed to run rustfmt: {error}")))?;
    {
        use std::io::Write;
        child
            .stdin
            .take()
            .ok_or("failed to open rustfmt stdin")?
            .write_all(input.as_bytes())?;
    }
    let output = child.wait_with_output()?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        )
        .into());
    }
    Ok(String::from_utf8(output.stdout)?)
}

fn expand_item(item: Item) -> syn::Result<TokenStream> {
    match item {
        Item::Struct(item) => expand_api_resource(item),
        other => Err(syn::Error::new_spanned(
            other,
            "ApiResource can only be generated from structs",
        )),
    }
}

fn expand_api_resource(input: syn::ItemStruct) -> syn::Result<TokenStream> {
    Ok(emit::ResourceSpec::parse(input)?.emit())
}

#[cfg(test)]
mod tests {
    use super::expand_item;
    use syn::parse_quote;

    #[test]
    fn rejects_resource_without_suffix() {
        let error = expand_item(parse_quote!(
            struct Widget {
                id: i32,
            }
        ))
        .unwrap_err();
        assert!(error.to_string().contains("ending in `Resource`"));
    }

    #[test]
    fn rejects_empty_resource_name() {
        let error = expand_item(parse_quote!(
            struct Resource {
                id: i32,
            }
        ))
        .unwrap_err();
        assert!(error.to_string().contains("non-empty resource name"));
    }

    #[test]
    fn rejects_non_struct_item() {
        let error = expand_item(parse_quote!(
            enum WidgetResource {
                First,
            }
        ))
        .unwrap_err();
        assert!(error.to_string().contains("generated from structs"));
    }

    #[test]
    fn rejects_unnamed_fields() {
        let error = expand_item(parse_quote!(
            struct WidgetResource(i32);
        ))
        .unwrap_err();
        assert!(error.to_string().contains("named fields"));
    }

    #[test]
    fn rejects_missing_display_field() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                value: String,
            }
        ))
        .unwrap_err();
        assert!(error.to_string().contains("field for Display"));
    }

    #[test]
    fn rejects_unknown_field_option() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(unknown)]
                name: String,
            }
        ))
        .unwrap_err();
        assert!(error.to_string().contains("unknown API field option"));
    }

    #[test]
    fn rejects_duplicate_field_option() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(optional, optional)]
                name: String,
            }
        ))
        .unwrap_err();
        assert!(error.to_string().contains("duplicate API field option"));
    }

    #[test]
    fn uses_configured_query_key() {
        let expanded = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(query_key = "from_widgets")]
                name: String,
            }
        ))
        .unwrap()
        .to_string();
        assert!(expanded.contains("\"from_widgets\""));
    }

    #[test]
    fn required_relationship_ids_remain_required_on_create_but_optional_on_patch() {
        let expanded: syn::File = syn::parse2(
            expand_item(parse_quote!(
                struct WidgetResource {
                    #[api(read_only)]
                    id: i32,
                    name: String,
                    #[api(as_id)]
                    collection: Collection,
                }
            ))
            .unwrap(),
        )
        .unwrap();

        let field_type = |struct_name: &str| {
            expanded
                .items
                .iter()
                .find_map(|item| match item {
                    syn::Item::Struct(item) if item.ident == struct_name => item
                        .fields
                        .iter()
                        .find(|field| field.ident.as_ref().is_some_and(|id| id == "collection_id"))
                        .map(|field| &field.ty),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("missing {struct_name}.collection_id"))
        };
        let is_option = |ty: &syn::Type| {
            matches!(
                ty,
                syn::Type::Path(path)
                    if path.qself.is_none()
                        && path.path.segments.last().is_some_and(|segment| segment.ident == "Option")
            )
        };

        assert!(!is_option(field_type("WidgetPost")));
        assert!(is_option(field_type("WidgetPatch")));
    }

    #[test]
    fn rejects_duplicate_query_key() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(query_key = "first", query_key = "second")]
                name: String,
            }
        ))
        .unwrap_err();
        assert!(
            error
                .to_string()
                .contains("duplicate API field option `query_key`")
        );
    }

    #[test]
    fn rejects_query_key_for_skipped_query_field() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(skip_query, query_key = "widgets")]
                name: String,
            }
        ))
        .unwrap_err();
        assert!(
            error
                .to_string()
                .contains("both `skip_query` and `query_key`")
        );
    }

    #[test]
    fn rejects_read_only_post_only_field() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(read_only, post_only)]
                name: String,
            }
        ))
        .unwrap_err();
        assert!(
            error
                .to_string()
                .contains("both `read_only` and `post_only`")
        );
    }

    #[test]
    fn rejects_optional_post_only_field() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(post_only, optional)]
                name: String,
            }
        ))
        .unwrap_err();
        assert!(
            error
                .to_string()
                .contains("`post_only` field cannot be optional")
        );
    }

    #[test]
    fn rejects_conflicting_field_defaults() {
        let error = expand_item(parse_quote!(
            struct WidgetResource {
                id: i32,
                #[api(default, default_local)]
                name: String,
            }
        ))
        .unwrap_err();
        assert!(
            error
                .to_string()
                .contains("both `default` and `default_local`")
        );
    }
}
